def compute_verified_local_orders_batch(last_seq: int, orders: list[dict[str, object]]) -> dict[str, object]:
    """Return the exact six-key integer batch payload for a nonempty, fully valid ascending order list."""
    import logging
    import re
    from datetime import date

    log = logging.getLogger(__name__)
    order_keys = {"seq", "date", "region", "units", "amount"}
    batch_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_amount_minor",
        "amount_by_region_minor",
    }
    date_re = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    if type(last_seq) is not int or last_seq < 0:
        raise ValueError("last_seq must be a JSON integer >= 0")
    if type(orders) is not list or not orders or len(orders) > 100:
        raise ValueError("orders must be a nonempty list with at most 100 entries")

    seen: set[int] = set()
    prior: int | None = None
    for index, order in enumerate(orders):
        label = f"order[{index}]"
        if type(order) is not dict or set(order.keys()) != order_keys or len(order) != 5:
            raise ValueError(f"{label} must contain exactly the five required keys")
        for field in ("seq", "units", "amount"):
            if type(order[field]) is not int:
                raise ValueError(f"{label}.{field} must be a JSON integer, not boolean")
        value = order["date"]
        if type(value) is not str or date_re.fullmatch(value) is None:
            raise ValueError(f"{label}.date must be exactly valid YYYY-MM-DD")
        try:
            parsed = date.fromisoformat(value)
        except ValueError as exc:
            raise ValueError(f"{label}.date was not a valid calendar date") from exc
        if parsed.isoformat() != value:
            raise ValueError(f"{label}.date was not canonical YYYY-MM-DD")
        if type(order["region"]) is not str:
            raise ValueError(f"{label}.region must be a string")
        seq = order["seq"]
        if seq <= last_seq:
            raise ValueError(f"{label}.seq must be greater than last_seq")
        if seq in seen:
            raise ValueError(f"duplicate seq {seq}")
        if prior is not None and seq <= prior:
            raise ValueError("orders must be strictly ascending by seq")
        seen.add(seq)
        prior = seq

    log.info("PHASE compute exact integer aggregates")
    total_units = 0
    total_amount = 0
    region_totals: dict[str, int] = {}
    for order in orders:
        total_units += order["units"]
        total_amount += order["amount"]
        region = order["region"]
        region_totals[region] = region_totals.get(region, 0) + order["amount"]

    payload: dict[str, object] = {
        "batch_start_seq": orders[0]["seq"],
        "batch_end_seq": orders[-1]["seq"],
        "order_count": len(orders),
        "total_units": total_units,
        "total_amount_minor": total_amount,
        "amount_by_region_minor": region_totals,
    }

    log.info("PHASE independently recompute and verify payload before delivery")
    check_units = sum((order["units"] for order in orders), 0)
    check_amount = sum((order["amount"] for order in orders), 0)
    check_regions: dict[str, int] = {}
    for order in orders:
        region = order["region"]
        check_regions[region] = check_regions.get(region, 0) + order["amount"]
    expected: dict[str, object] = {
        "batch_start_seq": orders[0]["seq"],
        "batch_end_seq": orders[len(orders) - 1]["seq"],
        "order_count": len(orders),
        "total_units": check_units,
        "total_amount_minor": check_amount,
        "amount_by_region_minor": check_regions,
    }

    if set(payload.keys()) != batch_keys or len(payload) != 6:
        raise ValueError("computed payload did not contain exactly the six required keys")
    for field in (
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_amount_minor",
    ):
        if type(payload[field]) is not int:
            raise ValueError(f"payload.{field} was not a JSON integer")
    region_payload = payload["amount_by_region_minor"]
    if type(region_payload) is not dict:
        raise ValueError("payload.amount_by_region_minor was not an object")
    if set(region_payload.keys()) != {order["region"] for order in orders}:
        raise ValueError("payload.amount_by_region_minor did not contain exactly every source region")
    if any(type(region) is not str or type(value) is not int for region, value in region_payload.items()):
        raise ValueError("payload.amount_by_region_minor had a non-string key or non-integer value")
    if payload != expected:
        raise ValueError("computed payload failed independent source-order verification")
    return payload

