def fetch_validated_local_orders() -> dict[str, object]:
    """Return exactly a nonnegative last_seq and a strictly validated pending-order list from the fixed local API."""
    import json
    import logging
    import re
    import urllib.error
    import urllib.request
    from datetime import date

    log = logging.getLogger(__name__)
    base = "http://127.0.0.1:18191"
    timeout_seconds = 20
    order_keys = {"seq", "date", "region", "units", "amount"}
    date_re = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    class DuplicateJSONKey(ValueError):
        pass

    def reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
        value: dict[str, object] = {}
        for key, item in pairs:
            if key in value:
                raise DuplicateJSONKey(f"duplicate JSON object key {key!r}")
            value[key] = item
        return value

    def decode(body: bytes, label: str) -> object:
        try:
            text = body.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RuntimeError(f"{label} body was not valid UTF-8: {exc}") from exc
        try:
            return json.loads(
                text,
                object_pairs_hook=reject_duplicate_keys,
                parse_constant=lambda token: (_ for _ in ()).throw(
                    ValueError(f"non-standard JSON constant {token}")
                ),
            )
        except (json.JSONDecodeError, DuplicateJSONKey, ValueError) as exc:
            raise RuntimeError(f"{label} JSON decode failed: {exc}") from exc

    def get(path: str) -> bytes:
        request = urllib.request.Request(
            base + path,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
                status = response.status
                body = response.read()
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", "replace")[:200]
            suffix = f"; body={detail!r}" if detail else ""
            raise RuntimeError(f"GET {path} returned HTTP {exc.code}{suffix}") from exc
        except Exception as exc:
            raise RuntimeError(f"GET {path} failed: {type(exc).__name__}: {exc}") from exc
        if not 200 <= status <= 299:
            raise RuntimeError(f"GET {path} returned unsuccessful HTTP {status}")
        return body

    def require_int(value: object, field: str) -> None:
        if type(value) is not int:
            raise RuntimeError(f"{field} was {type(value).__name__}, expected JSON integer")

    def require_date(value: object, field: str) -> None:
        if type(value) is not str:
            raise RuntimeError(f"{field} was {type(value).__name__}, expected string")
        if date_re.fullmatch(value) is None:
            raise RuntimeError(f"{field}={value!r} was not exactly YYYY-MM-DD")
        try:
            parsed = date.fromisoformat(value)
        except ValueError as exc:
            raise RuntimeError(f"{field}={value!r} was not a valid calendar date") from exc
        if parsed.isoformat() != value:
            raise RuntimeError(f"{field}={value!r} was not canonical YYYY-MM-DD")

    log.info("PHASE fetch and validate last processed sequence")
    last_value = decode(get("/batches/last"), "GET /batches/last")
    if type(last_value) is not dict:
        raise RuntimeError(
            f"GET /batches/last JSON was {type(last_value).__name__}, expected object"
        )
    if set(last_value.keys()) != {"last_seq"} or len(last_value) != 1:
        raise RuntimeError(
            f"GET /batches/last keys were {sorted(map(str, last_value.keys()))!r}, expected exactly ['last_seq']"
        )
    last_seq = last_value["last_seq"]
    require_int(last_seq, "last_seq")
    if last_seq < 0:
        raise RuntimeError(f"last_seq was {last_seq}, expected >= 0")

    log.info("PHASE fetch and validate pending orders after seq=%d", last_seq)
    orders = decode(get(f"/orders?after={last_seq}"), "GET /orders")
    if type(orders) is not list:
        raise RuntimeError(f"GET /orders JSON was {type(orders).__name__}, expected array")
    if len(orders) > 100:
        raise RuntimeError(f"GET /orders returned {len(orders)} entries, maximum is 100")

    seen: set[int] = set()
    prior: int | None = None
    for index, order in enumerate(orders):
        label = f"order[{index}]"
        if type(order) is not dict:
            raise RuntimeError(f"{label} was {type(order).__name__}, expected object")
        if set(order.keys()) != order_keys or len(order) != 5:
            raise RuntimeError(
                f"{label} keys were {sorted(map(str, order.keys()))!r}, expected exactly {sorted(order_keys)!r}"
            )
        require_int(order["seq"], f"{label}.seq")
        require_int(order["units"], f"{label}.units")
        require_int(order["amount"], f"{label}.amount")
        require_date(order["date"], f"{label}.date")
        if type(order["region"]) is not str:
            raise RuntimeError(
                f"{label}.region was {type(order['region']).__name__}, expected string"
            )
        seq = order["seq"]
        if seq <= last_seq:
            raise RuntimeError(f"{label}.seq was {seq}, expected > last_seq {last_seq}")
        if seq in seen:
            raise RuntimeError(f"duplicate seq {seq} at {label}")
        if prior is not None and seq <= prior:
            raise RuntimeError(f"orders were not strictly ascending: seq {seq} followed {prior}")
        seen.add(seq)
        prior = seq

    return {"last_seq": last_seq, "orders": orders}
